require_once __DIR__.'/inc/ai/Bootstrap.php';require_once __DIR__.'/inc/saas/Commerce.php';require_once __DIR__.'/inc/saas/Usage.php';require_once __DIR__.'/inc/ProjectMembers.php';header('Cache-Control: no-store');header('Referrer-Policy: no-referrer');
if(!isUser())redirect('/?action=login');$service=new SaaSAccounts();$commerce=new SaaSCommerce($service);$owned=$service->owned();$id=$_GET['account']??($owned[0]['id']??'');$error='';$message='';$account=null;
try{if($id)$account=$service->account($id);if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){RequestSecurity::enforce();if(!$account)throw new RuntimeException('حساب مشتری موجود نیست.');$action=$_POST['action']??'';
 if($action==='allocate')$service->allocate($id,$_POST['pid']??'',(int)($_POST['mb']??0));
 elseif($action==='transfer')$service->transfer($id,$_POST['from']??'',$_POST['to']??'',(int)($_POST['credits']??0),$_POST['request_id']??'');
 elseif($action==='activate')$service->activate($id,$_POST['pid']??'',$_POST['employee']??'nahal',!empty($_POST['enabled']));
 elseif($action==='create_project'){$pid=$service->createProject($id,$_POST['name']??'',$_POST['request_id']??'');if(!SessionIdentity::selectCreated($pid,$account['anchor_project']))throw new RuntimeException('پروژه ساخته شد؛ برای ورود دوباره وارد حساب شوید.');unset($_SESSION['project_selection_required']);redirect(ProjectOnboarding::url($pid));}
 elseif($action==='checkout'){redirect($commerce->checkout($id,$_POST['sku']??'',$_POST['pid']??'',$_POST['request_id']??''));}
 elseif($action==='renew'){redirect($commerce->renew($id,$_POST['cycle']??'',$_POST['request_id']??''));}
 else throw new RuntimeException('عملیات معتبر نیست.');$message='تغییرات ثبت شد.';$account=$service->account($id);}}
catch(Throwable $e){http_response_code(422);$error=$e instanceof RuntimeException?$e->getMessage():'عملیات ناموفق بود.';}
function sa_h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function sa_request(){echo '<input type="hidden" name="request_id" value="'.bin2hex(random_bytes(16)).'">';}
?><!doctype html><html dir="rtl" lang="fa"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>حساب و اشتراک مارک‌شو</title><link rel="stylesheet" href="/panel/assets/workspace-shell.css"><link rel="stylesheet" href="/panel/assets/saas.css?v=1"></head><body class="workspace-page"><main class="workspace-shell saas-shell"><header class="saas-top"><a href="/panel/workspace.php">← میزکارها</a><span>مارک‌شو / حساب مشتری</span></header><div class="saas-hero"><span>یک اشتراک برای همهٔ پروژه‌های شما</span><h1>حساب، ظرفیت و اعتبار</h1><p>مدت اشتراک مشترک است؛ حجم را تخصیص دهید و اعتبار آزاد را بین پروژه‌ها جابه‌جا کنید.</p></div><?php if($error):?><p class="saas-alert error" role="alert"><?=sa_h($error)?></p><?php endif;?><?php if($message):?><p class="saas-alert" role="status"><?=sa_h($message)?></p><?php endif;?>
<?php if(!$account):?><section class="saas-card"><h2>هنوز اشتراک حسابی ثبت نشده است</h2><p>خریدهای جدید پس از تأیید پرداخت حساب مشتری می‌سازند. برای انتقال پروژهٔ قدیمی، با تیم مرکزی تماس بگیرید؛ اطلاعات و اعتبار قبلی خودکار تغییر نمی‌کند.</p><a href="/panel/support.php">تماس با پشتیبانی</a></section><?php else:?>
<?php if(count($owned)>1):?><form method="get"><label>حساب<select name="account"><?php foreach($owned as $a):?><option value="<?=sa_h($a['id'])?>" <?=$a['id']===$id?'selected':''?>><?=sa_h($a['owner'])?></option><?php endforeach;?></select></label><button>نمایش</button></form><?php endif;?>
<div class="saas-metrics"><article><small>اشتراک حساب</small><strong><?=sa_h($account['plan_name'])?></strong><span><?=SaaSAccounts::active($account)?'فعال':'نیازمند تمدید'?> · پایان <?=formatPersianDate($account['expires_at'],'Y/m/d')?></span></article><article><small>پروژه‌ها</small><strong><?=count($account['projects'])?> / <?=$account['limits']['projects']?></strong><span>اعضا: سقف <?=$account['limits']['seats']?> نفر یکتا در حساب</span></article><article><small>حجم کل حساب</small><strong><?=number_format($account['limits']['storage_mb'])?> MB</strong><span>تخصیص‌یافته: <?=number_format(array_sum($account['allocations']))?> MB</span></article></div>
<section class="saas-card"><h2>پروژه‌ها و اعتبار مستقل</h2><div class="saas-grid"><?php foreach(array_keys($account['projects']) as $pid):$p=getCurrentProject($pid,true);$w=$account['wallets'][$pid]??['balance'=>0,'reserved'=>0];?><article class="saas-project"><h3><?=sa_h($p['name']??'پروژهٔ حذف‌شده')?></h3><p>کردیت آزاد: <b><?=number_format($w['balance']-$w['reserved'])?></b> · رزروشده: <?=number_format($w['reserved'])?></p><p>مدت مشترک: تا <?=formatPersianDate($account['expires_at'],'Y/m/d')?></p><form method="post"><input type="hidden" name="pid" value="<?=sa_h($pid)?>"><label>حجم پروژه (MB)<input type="number" name="mb" min="1" value="<?=(int)($account['allocations'][$pid]??0)?>"></label><button name="action" value="allocate">ثبت تخصیص حجم</button></form><?php foreach(['nahal'=>'نهال','ehsan'=>'احسان','aria'=>'آریا'] as $employee=>$name):?><form method="post"><input type="hidden" name="pid" value="<?=sa_h($pid)?>"><input type="hidden" name="employee" value="<?=$employee?>"><label class="saas-toggle"><input type="checkbox" name="enabled" <?=!empty($account['active_employees'][$employee][$pid])?'checked':''?>> <?=$name?> در این پروژه فعال باشد</label><button name="action" value="activate">ثبت فعال‌سازی <?=$name?></button></form><?php endforeach; SaaSUsage::render($service->state(),$pid,'sa_h');?></article><?php endforeach;?></div></section>
<div class="saas-grid"><section class="saas-card"><h2>ساخت پروژهٔ تازه</h2><p>از ظرفیت همین اشتراک استفاده می‌شود و راه‌اندازی از ابتدا انجام می‌شود. پس از ساخت، از همین صفحه برای پروژه حجم تخصیص دهید تا بارگذاری فایل فعال شود.</p><form method="post"><?php sa_request();?><label>نام پروژه<input name="name" required maxlength="150"></label><button name="action" value="create_project">ساخت و شروع راه‌اندازی</button></form></section><section class="saas-card"><h2>انتقال اعتبار آزاد</h2><p>اعتبار رزروشده قابل انتقال نیست. مجموع اعتبار حساب تغییر نمی‌کند.</p><form method="post"><?php sa_request();foreach(['from'=>'از پروژه','to'=>'به پروژه'] as $key=>$label):?><label><?=$label?><select name="<?=$key?>"><?php foreach(array_keys($account['projects']) as $pid):?><option value="<?=sa_h($pid)?>"><?=sa_h(getCurrentProject($pid,true)['name']??$pid)?></option><?php endforeach;?></select></label><?php endforeach;?><label>مقدار کردیت<input type="number" name="credits" min="1" required></label><button name="action" value="transfer">انتقال اعتبار</button></form></section></div>
<section class="saas-card"><h2>تمدید اشتراک همهٔ پروژه‌ها</h2><form method="post"><?php sa_request();?><label>دوره<select name="cycle"><option value="monthly">یک ماه</option><option value="yearly">یک سال</option></select></label><button name="action" value="renew">مشاهده و پرداخت درگاه</button></form></section>
<section class="saas-card"><h2>خرید ظرفیت، کردیت و دسترسی کارمند</h2><p>دسترسی نهال: <?=($account['employees']['nahal']??0)?> پروژه · فعال در <?=count($account['active_employees']['nahal']??[])?> پروژه. فعال‌سازی هزینهٔ مصرف ندارد؛ اجرای تولید تصویر کردیت مصرف می‌کند.</p><div class="saas-grid"><?php foreach($commerce->products() as $product):?><article class="saas-project"><h3><?=sa_h($product['name'])?></h3><strong><?=number_format($product['price_toman'])?> تومان</strong><p><?=number_format($product['units'])?> <?=sa_h(['credits'=>'کردیت','projects'=>'پروژهٔ اضافه','seats'=>'عضو اضافه','storage_mb'=>'مگابایت اضافه','nahal'=>'ظرفیت فعال‌سازی نهال','ehsan'=>'ظرفیت فعال‌سازی احسان'][$product['kind']])?></p><form method="post"><?php sa_request();?><input type="hidden" name="sku" value="<?=sa_h($product['id'])?>"><?php if($product['kind']==='credits'):?><label>پروژهٔ دریافت اعتبار<select name="pid"><?php foreach(array_keys($account['projects']) as $pid):?><option value="<?=sa_h($pid)?>"><?=sa_h(getCurrentProject($pid,true)['name']??$pid)?></option><?php endforeach;?></select></label><?php endif;?><button name="action" value="checkout">خرید و پرداخت</button></form></article><?php endforeach;?></div><?php if(!$commerce->products()):?><p>هنوز بستهٔ قابل خرید توسط تیم مرکزی تعریف نشده است.</p><?php endif;?></section>
<section class="saas-card"><h2>خریدهای حساب</h2><?php foreach(array_reverse($service->state()['orders']??[]) as $order):if($order['account']!==$id)continue;?><p><?=sa_h($order['product']['name'])?> · <?=sa_h(['paid'=>'پرداخت و اعمال شده','pending'=>'در انتظار پرداخت','preparing'=>'نیازمند بررسی وضعیت درگاه'][$order['state']]??$order['state'])?> · <code><?=sa_h($order['id'])?></code></p><?php endforeach;?></section><?php endif;?></main></body></html>
